const a={ui:{fig:"Fig. 4",title:"Fondo separato",svgLabel:"Un disegno isometrico di come si cuce un fondo separato: le pareti cucite a tubo, i centri del fondo e del tubo segnati con le pieghe, il tubo al rovescio appoggiato sul fondo, segno su segno e fermato con le clip, il margine delle pareti con un taglietto a ogni angolo, il fondo cucito un lato alla volta, la borsa rivoltata, con il fondo piatto.",prev:"Passo precedente",dot:(o,i)=>o?`Passo ${o}: ${i}`:i,start:"Passo passo →",next:"Avanti →",overview:"Panoramica",stepOf:(o,i)=>`Passo ${o} di ${i}`,machine:o=>`Macchina: ${o.toLowerCase()}`,inThisStep:"In questo passo",takeApart:"Rimetti in piedi",putTogether:"Mostra il fondo",replay:"↻ Ripeti",parts:"Parti",allSteps:"Istruzioni passo passo",endView:"SEZIONE"},stitches:{straight:"Punto dritto"},labels:{rightSides:"dritto contro dritto",bothSides:"cuci i due lati",aTube:"un tubo aperto ai due capi",foldCrease:"piega a metà, segna la piega",markMiddle:"un segno a ogni centro",seamMark:"cucitura laterale = segno",insideOut:"al rovescio",markOnMark:"segno su segno",clipBetween:"poi le clip in mezzo",clipCorner:"taglietto nell'angolo",notThrough:"senza tagliare la cucitura",backstitch:"fermatura",oneSide:"un lato alla volta",stopTurn:"fermati e gira",allRound:"tutto intorno",turnOut:"rivolta sul dritto",flatBottom:"un fondo piatto",baseSeam:"cucitura intorno al fondo"},steps:[{title:"Fondo separato",text:"Il fondo della borsa, la borsa capovolta: il fondo è un pezzo a sé, qui in un altro tessuto, cucito alle pareti tutto intorno. Tocca la borsa per rimetterla in piedi."},{title:"Cuci le pareti a tubo",text:"Appoggia il davanti sul dietro, dritto contro dritto, e cuci i due lati: un tubo, aperto ai due capi. Il fondo è un pezzo a sé.",details:["Appoggia il davanti sul dietro, dritto contro dritto, e fissali con le clip.","Cuci i due lati, dall'alto in basso.","Anche in basso il tubo resta aperto: il fondo è un pezzo a sé, cucito dopo.","Se le pareti sono tagliate in un pezzo solo, basta una cucitura per chiudere il tubo."]},{title:"Segna i centri",text:"Piega il fondo a metà e segna la piega, poi piegalo a metà nell'altro senso: fai un segno al centro di ogni lato. Piega a metà anche il tubo e segna la piega: le pieghe e le cuciture laterali ne segnano i centri.",details:["Piega il fondo a metà e segna la piega con il ferro o con le dita.","Aprilo, piegalo a metà nell'altro senso e segna di nuovo la piega.","Fai un segno al centro di ogni lato, sul bordo, dove arriva una piega.","Piega il tubo a metà, cucitura laterale su cucitura laterale, e segna la piega: le pieghe segnano il centro del davanti e del dietro.","Anche le cuciture laterali sono segni: il tubo è diviso in quattro, come il fondo."]},{title:"Segno su segno",text:"Rivolta il tubo al rovescio e appoggialo sul fondo, dritto contro dritto, bordi pari. Prima metti segno su segno, le cuciture laterali e le pieghe sui centri del fondo, poi le clip in mezzo.",details:["Il tubo è al rovescio e il fondo ha il dritto in su: i due dritti sono uno contro l'altro.","Allinea i bordi del tubo e del fondo tutto intorno; il margine delle pareti appoggia sul bordo del fondo.","Prima segno su segno: ogni cucitura laterale al centro di un lato corto, ogni piega al centro di un lato lungo.","Fissa prima i segni con le clip, poi metti le clip in mezzo."]},{title:"Taglietti agli angoli",text:"A ogni angolo del fondo fai un taglietto nel margine delle pareti, dritto verso l'angolo, fin quasi alla linea di cucitura, senza tagliare la cucitura: così le pareti girano l'angolo.",details:["Trova dove ogni angolo del fondo incontra le pareti.","Fai un taglietto nel margine delle pareti verso l'angolo, fin quasi alla linea di cucitura: senza tagliare la cucitura.","Il margine si apre e sta piatto intorno all'angolo, e l'angolo resta netto.","Fai lo stesso a tutti gli angoli."]},{title:"Cuci il fondo",text:"Cuci un lato alla volta: comincia con la fermatura, fermati a un margine di cucitura dall'angolo con l'ago giù, gira l'angolo e cuci il lato successivo.",details:["Cuci con il tubo al rovescio, sulla linea di cucitura.","Comincia al centro di un lato, con la fermatura.","Fermati a un margine di cucitura dall'angolo, con l'ago nel tessuto.","Alza il piedino, gira l'angolo, abbassa il piedino e cuci il lato successivo.","Togli le clip man mano che arrivi e cuci tutto intorno; alla fine, di nuovo la fermatura."]},{title:"Rivolta",text:"Rivolta la borsa sul dritto e fai uscire bene gli angoli: un fondo piatto, cucito alle pareti tutto intorno.",details:["Rivolta la borsa sul dritto e fai uscire gli angoli.","Il fondo sta piatto e la cucitura corre lungo il suo bordo.","Per un fondo rigido il rinforzo va sul fondo: teletta termoadesiva stirata prima di cucirlo, oppure dopo un inserto rigido appoggiato all'interno."]}],legend:[{title:"Fondo",text:"un pezzo a sé · qui in un altro tessuto"},{title:"Cucitura del fondo",text:"unisce le pareti al fondo, tutto intorno"},{title:"Angoli",text:"margine delle pareti con un taglietto, così l'angolo resta netto"},{title:"Cuciture laterali",text:"ognuna arriva al centro di un lato corto del fondo"}]};export{a as default};
